        return {}
    header_row = total_rows[0].split(",")
    if len(header_row) < 2:
        return {}
    name, amount = header_row[0], header_row[1]
    totals = {}
    for row in total_rows[1:]:
        if not row:
            continue
        parts = row.split(",")
        if len(parts) < 2:
            continue
        name, amount_str = parts[0], parts[1]
        total_amount = Decimal(amount_str)
        totals[name] = total_amount
    return totals

